  "lsn.right": "Correct !", "lsn.wrong": "Pas tout à fait…", "lsn.endPass": "Réussi !", "lsn.endFail": "Presque !", "lsn.endPassD": "Vous maîtrisez. Passez à la leçon suivante.", "lsn.endFailD": "Relisez l'explication et réessayez.",
  "cat.basic": "Premiers pas", "cat.bets": "Mises et gains", "cat.roads": "Lire les routes", "cat.money": "Protéger votre argent",
