  'sy.n.flat': 'ثابت (الرهان نفسه دائمًا)', 'sy.n.martin': 'مارتينغيل (ضاعِف بعد الخسارة)', 'sy.n.paroli': 'بارولي (ضاعِف بعد الفوز، أعد بعد 3)', 'sy.n.p1326': '1-3-2-6', 'sy.n.fibo': 'فيبوناتشي', 'sy.n.dalem': 'دالمبير (+1 بعد الخسارة، −1 بعد الفوز)',
