Object.assign(I18N.ko, {"ck.best":"이 슈에서 가장 손해가 적은 베팅","ck.flip":"드문 상황: 남은 카드의 치우침 때문에 지금은 {w} 쪽이 손해가 더 적습니다 (차이는 아주 작습니다).","gr.main":"{k}: 하우스 엣지 {e} — 손해가 가장 적은 축에 드는 베팅입니다.","gr.side":"{k}: 하우스 엣지 {e}. 재미로 조금만 거세요.","gr.size.ok":"베팅액은 보유 칩의 {n}% — 무리 없는 크기입니다.","gr.size.big":"베팅액은 보유 칩의 {n}% — 조금 큽니다 (보통 1–5%가 기준).","gr.size.huge":"베팅액은 보유 칩의 {n}% — 몇 번만 져도 크게 줄어듭니다.","gr.chase":"진 뒤에 베팅액을 {a}에서 {b}(으)로 올렸습니다. 손실을 만회하려는 추격 베팅은 손해를 키우기 쉽습니다.","gr.h.g":"◎ 좋은 베팅","gr.h.m":"△ 주의할 점이 있습니다","gr.h.b":"✕ 다시 생각해 볼 베팅","pl.h":"자금 계획 (이번 세션)","pl.unit":"베팅 기준 (보유 칩의 2%)","pl.stop":"손절 라인 (시작 금액의 70%)","pl.goal":"목표 (시작 금액의 120%)","pl.atStop":"손절 라인에 도달했습니다. 여기서 끝내는 것이 가장 효과적인 자금 관리입니다.","pl.atGoal":"목표에 도달했습니다! '정산'으로 승리를 확정하는 것도 훌륭한 전략입니다.","lg.h":"매 게임 뱅커에 같은 금액을 걸면…","lg.n":"{n}게임 후","lg.help":"이기고 있을 확률입니다. 많이 할수록 하우스 엣지가 드러나 이 확률은 낮아집니다.","ck.won":"이겼습니다 — 하지만 이번 게임의 이론상 비용은 여전히 {e}입니다. 승패는 운이, 비용은 베팅 방식이 정합니다.","ck.lost":"졌습니다. 이론상 비용은 {e}이고 나머지는 운입니다. 베팅이 합리적이었다면 신경 쓰지 마세요.","ck.push":"푸시입니다. 이번 게임의 이론상 비용은 {e}입니다."});
Object.assign(I18N.es, {"ck.best":"La apuesta más barata en este sabot","ck.flip":"Una situación rara: las cartas que quedan hacen ahora que {w} sea la apuesta más barata (por muy poco).","gr.main":"{k}: ventaja de la casa {e}, una de las apuestas más baratas que existen.","gr.side":"{k}: ventaja de la casa {e}. Apuesta poco, solo por diversión.","gr.size.ok":"Tu apuesta es el {n}% de tus fichas: un tamaño cómodo.","gr.size.big":"Tu apuesta es el {n}% de tus fichas: algo alta (lo habitual es un 1–5%).","gr.size.huge":"Tu apuesta es el {n}% de tus fichas: unas pocas derrotas se llevarán un buen mordisco.","gr.chase":"Tras perder, subiste la apuesta de {a} a {b}. Intentar recuperar las pérdidas suele hacerlas mayores.","gr.h.g":"◎ Bien jugado","gr.h.m":"△ Algo a tener en cuenta","gr.h.b":"✕ Conviene replanteárselo","pl.h":"Plan de dinero (esta sesión)","pl.unit":"Tamaño de apuesta (2% de las fichas)","pl.stop":"Límite de pérdidas (70% del inicio)","pl.goal":"Objetivo (120% del inicio)","pl.atStop":"Has llegado a tu límite de pérdidas. Parar aquí es la gestión del dinero que mejor funciona.","pl.atGoal":"¡Objetivo alcanzado! «Retirarse» para asegurar la ganancia es una buena estrategia.","lg.h":"Apostando lo mismo a la Banca en cada mano…","lg.n":"tras {n}","lg.help":"La probabilidad de ir ganando. Cuanto más juegas, más se nota la ventaja de la casa y más baja esta cifra.","ck.won":"Has ganado, pero en teoría esta mano te costó {e}. La suerte decide si ganas o pierdes; tus apuestas deciden el coste.","ck.lost":"Has perdido. El coste teórico fue {e}; el resto fue suerte. Si la apuesta era sensata, no te preocupes.","ck.push":"Apuesta devuelta. El coste teórico de esta mano fue {e}."});
Object.assign(I18N.fr, {"ck.best":"La mise la moins coûteuse de ce sabot","ck.flip":"Situation rare : les cartes restantes font de {w} la mise la moins coûteuse (de très peu).","gr.main":"{k} : avantage de la maison {e} — l'une des mises les moins coûteuses qui soient.","gr.side":"{k} : avantage de la maison {e}. Misez petit, juste pour le plaisir.","gr.size.ok":"Votre mise représente {n} % de vos jetons — une taille confortable.","gr.size.big":"Votre mise représente {n} % de vos jetons — un peu élevée (1–5 % est un repère courant).","gr.size.huge":"Votre mise représente {n} % de vos jetons — quelques pertes feront un gros trou.","gr.chase":"Après une perte, vous avez augmenté la mise de {a} à {b}. Courir après ses pertes tend à les aggraver.","gr.h.g":"◎ Bien joué","gr.h.m":"△ Un point à surveiller","gr.h.b":"✕ À reconsidérer","pl.h":"Plan de jeu (cette session)","pl.unit":"Taille de mise (2 % des jetons)","pl.stop":"Seuil de perte (70 % du départ)","pl.goal":"Objectif (120 % du départ)","pl.atStop":"Vous avez atteint votre seuil de perte. S'arrêter ici, c'est la gestion de bankroll la plus efficace.","pl.atGoal":"Objectif atteint ! « Encaisser » pour verrouiller le gain est une excellente stratégie.","lg.h":"En misant la même somme sur la Banque à chaque coup…","lg.n":"après {n}","lg.help":"La probabilité d'être gagnant. Plus vous jouez, plus l'avantage de la maison se fait sentir et plus elle baisse.","ck.won":"Vous avez gagné — mais ce coup vous a quand même coûté {e} en théorie. La chance décide des gains et des pertes ; vos mises décident du coût.","ck.lost":"Vous avez perdu. Le coût théorique était de {e} ; le reste, c'est la chance. Si la mise était judicieuse, ne vous en faites pas.","ck.push":"Remboursé. Le coût théorique de ce coup était de {e}."});
Object.assign(I18N.pt, {"ck.best":"A aposta mais barata neste sapato","ck.flip":"Situação rara: as cartas que restam agora tornam {w} a aposta mais barata (por uma margem mínima).","gr.main":"{k}: vantagem da casa {e} — uma das apostas mais baratas que existem.","gr.side":"{k}: vantagem da casa {e}. Aposte pouco, só por diversão.","gr.size.ok":"Sua aposta é {n}% das suas fichas — um tamanho confortável.","gr.size.big":"Sua aposta é {n}% das suas fichas — um pouco alta (1–5% é a referência comum).","gr.size.huge":"Sua aposta é {n}% das suas fichas — poucas derrotas já vão levar uma boa parte.","gr.chase":"Depois de perder, você aumentou a aposta de {a} para {b}. Correr atrás do prejuízo costuma aumentá-lo.","gr.h.g":"◎ Bem jogado","gr.h.m":"△ Algo para observar","gr.h.b":"✕ Vale repensar","pl.h":"Plano de dinheiro (esta sessão)","pl.unit":"Tamanho da aposta (2% das fichas)","pl.stop":"Limite de perda (70% do início)","pl.goal":"Meta (120% do início)","pl.atStop":"Você chegou ao seu limite de perda. Parar aqui é a gestão de dinheiro que mais funciona.","pl.atGoal":"Meta atingida! \"Sair\" para garantir o ganho é uma ótima estratégia.","lg.h":"Apostando o mesmo valor na Banca a cada rodada…","lg.n":"após {n}","lg.help":"A chance de estar ganhando. Quanto mais você joga, mais a vantagem da casa aparece e menor fica esse número.","ck.won":"Você ganhou — mas, em teoria, esta rodada ainda custou {e}. A sorte decide ganhos e perdas; suas apostas decidem o custo.","ck.lost":"Você perdeu. O custo teórico foi {e}; o resto foi sorte. Se a aposta foi sensata, não se preocupe.","ck.push":"Aposta devolvida. O custo teórico desta rodada foi {e}."});
